package main

// emit.go — writes the generated Go file, the TypeScript declarations and the JS entry point.

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"strings"
)

// header starts every generated file.
const header = "Code generated by napi-go-gen; DO NOT EDIT."

// goSource returns the generated Go file: one init function registering every export, in source
// order (functions, then classes, then constants).
func (m *module) goSource() ([]byte, error) {
	var b bytes.Buffer
	fmt.Fprintf(&b, "// %s\n\npackage %s\n\nimport %q\n\nfunc init() {\n", header, m.pkgName, napiPath)
	for _, f := range m.funcs {
		fmt.Fprintf(&b, "\tnapi.Export(%q, napi.%s(%s))\n", f.jsName, f.wrapper, f.goName)
	}
	for _, c := range m.classes {
		ctor := "napi.CtorDef[" + c.goName + "]{}"
		if c.ctor != nil {
			ctor = "napi." + c.ctor.wrapper + "(" + c.ctor.goName + ")"
		}
		fmt.Fprintf(&b, "\tnapi.Export(%q, napi.NewClass(%s)", c.jsName, ctor)
		for _, me := range c.methods {
			fmt.Fprintf(&b, ".\n\t\tMethod(%q, napi.%s((*%s).%s))", me.jsName, me.wrapper, c.goName, me.goName)
		}
		for _, a := range c.accessors {
			fn := map[bool]string{false: "Accessor", true: "AccessorE"}[a.fallible]
			set := "nil"
			if a.setter != "" {
				set = "(*" + c.goName + ")." + a.setter
			}
			fmt.Fprintf(&b, ".\n\t\tAccessor(%q, napi.%s((*%s).%s, %s))", a.jsName, fn, c.goName, a.getter, set)
		}
		for _, s := range c.statics {
			fmt.Fprintf(&b, ".\n\t\tStatic(%q, napi.%s(%s))", s.jsName, s.wrapper, s.goName)
		}
		for _, k := range c.consts {
			fmt.Fprintf(&b, ".\n\t\tStaticConst(%q, %s)", k.jsName, k.goName)
		}
		b.WriteString(")\n")
	}
	for _, k := range m.consts {
		fmt.Fprintf(&b, "\tnapi.Export(%q, napi.Const(%s))\n", k.jsName, k.goName)
	}
	b.WriteString("}\n")
	src, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("internal error: generated Go does not parse: %w\n%s", err, b.Bytes())
	}
	return src, nil
}

// dts returns the TypeScript declarations: interfaces, functions, classes and constants.
func (m *module) dts() []byte {
	var b bytes.Buffer
	fmt.Fprintf(&b, "// %s\n/* eslint-disable */\n", header)
	for _, o := range m.objects {
		b.WriteString("\n")
		jsdoc(&b, "", o.doc)
		fmt.Fprintf(&b, "export interface %s {\n", o.name)
		for _, f := range o.fields {
			jsdoc(&b, "  ", f.doc)
			fmt.Fprintf(&b, "  %s%s: %s\n", propName(f.name), map[bool]string{true: "?", false: ""}[f.optional], f.ts)
		}
		b.WriteString("}\n")
	}
	for _, f := range m.funcs {
		b.WriteString("\n")
		jsdoc(&b, "", f.doc)
		fmt.Fprintf(&b, "export declare function %s(%s): %s\n", f.jsName, tsParams(f), f.ret)
	}
	for _, c := range m.classes {
		b.WriteString("\n")
		jsdoc(&b, "", c.doc)
		fmt.Fprintf(&b, "export declare class %s {\n", c.jsName)
		if c.ctor != nil {
			jsdoc(&b, "  ", c.ctor.doc)
			fmt.Fprintf(&b, "  constructor(%s)\n", tsParams(c.ctor))
		} else {
			b.WriteString("  /** Instances are created by the addon only. */\n  private constructor()\n")
		}
		// Members in source order, whatever their kind.
		type member struct {
			pos  int
			emit func()
		}
		var members []member
		for _, me := range c.methods {
			members = append(members, member{int(me.pos), func() {
				jsdoc(&b, "  ", me.doc)
				fmt.Fprintf(&b, "  %s(%s): %s\n", propName(me.jsName), tsParams(me), me.ret)
			}})
		}
		for _, a := range c.accessors {
			members = append(members, member{int(a.pos), func() {
				jsdoc(&b, "  ", a.doc)
				fmt.Fprintf(&b, "  get %s(): %s\n", propName(a.jsName), a.ts)
				if a.setter != "" {
					fmt.Fprintf(&b, "  set %s(value: %s)\n", propName(a.jsName), a.ts)
				}
			}})
		}
		for _, s := range c.statics {
			members = append(members, member{int(s.pos), func() {
				jsdoc(&b, "  ", s.doc)
				fmt.Fprintf(&b, "  static %s(%s): %s\n", propName(s.jsName), tsParams(s), s.ret)
			}})
		}
		for _, k := range c.consts {
			members = append(members, member{int(k.pos), func() {
				jsdoc(&b, "  ", k.doc)
				fmt.Fprintf(&b, "  static readonly %s: %s\n", propName(k.jsName), k.ts)
			}})
		}
		sort.SliceStable(members, func(i, j int) bool { return members[i].pos < members[j].pos })
		for _, me := range members {
			me.emit()
		}
		b.WriteString("}\n")
	}
	for _, k := range m.consts {
		b.WriteString("\n")
		jsdoc(&b, "", k.doc)
		fmt.Fprintf(&b, "export declare const %s: %s\n", k.jsName, k.ts)
	}
	return b.Bytes()
}

func tsParams(f *funcModel) string {
	parts := make([]string, 0, len(f.params)+1)
	for _, p := range f.params {
		parts = append(parts, p.name+": "+p.ts)
	}
	if f.rest {
		parts = append(parts, "...args: any[]")
	}
	return strings.Join(parts, ", ")
}

// jsdoc writes doc as a JSDoc comment, if there is one.
func jsdoc(b *bytes.Buffer, indent, doc string) {
	if doc == "" {
		return
	}
	doc = strings.ReplaceAll(doc, "*/", "*\\/")
	lines := strings.Split(doc, "\n")
	if len(lines) == 1 {
		fmt.Fprintf(b, "%s/** %s */\n", indent, lines[0])
		return
	}
	fmt.Fprintf(b, "%s/**\n", indent)
	for _, l := range lines {
		fmt.Fprintf(b, "%s%s\n", indent, strings.TrimRight(" * "+l, " "))
	}
	fmt.Fprintf(b, "%s */\n", indent)
}

// jsEntry returns the JS entry point: it loads name.node from its own directory.
func jsEntry(name string) []byte {
	return []byte(fmt.Sprintf("// %s\n'use strict'\n\nmodule.exports = require(%s)\n", header, jsString("./"+name+".node")))
}

// jsString quotes s as a JS string literal.
func jsString(s string) string {
	r := strings.NewReplacer(`\`, `\\`, `'`, `\'`, "\n", `\n`, "\r", `\r`)
	return "'" + r.Replace(s) + "'"
}
